CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stories (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, edit_token TEXT, name1 TEXT NOT NULL, name2 TEXT NOT NULL, start_date TEXT, phrase TEXT, message TEXT, music TEXT, theme TEXT NOT NULL DEFAULT 'rose', status TEXT NOT NULL DEFAULT 'draft', plan TEXT NOT NULL DEFAULT 'memorias', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, story_id TEXT NOT NULL, event_date TEXT, title TEXT NOT NULL, body TEXT, FOREIGN KEY(story_id) REFERENCES stories(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, story_id TEXT NOT NULL, url TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(story_id) REFERENCES stories(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, story_id TEXT NOT NULL, reference TEXT UNIQUE NOT NULL, plan TEXT NOT NULL, amount_mzn INTEGER NOT NULL, payment_method TEXT, payment_id TEXT, status TEXT NOT NULL DEFAULT 'PENDING', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, paid_at TEXT, FOREIGN KEY(story_id) REFERENCES stories(id));
CREATE TABLE IF NOT EXISTS webhook_events (event_id TEXT PRIMARY KEY, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_stories_slug ON stories(slug);
CREATE INDEX IF NOT EXISTS idx_orders_reference ON orders(reference);
